<canvas id="c"></canvas>
<script>
(function () {
  'use strict';

  /* ================================================================
     Constantes (unidades: pixels e segundos)
     ================================================================ */
  var SIDES    = 9;                          // non&#225;gono regular
  var POLY_R   = 260;                        // raio (centro -> v&#233;rtese)
  var PERIOD   = 7;                          // segundos por volta completa
  var OMEGA    = 2 * Math.PI / PERIOD;       // rad/s, sentido hor&#225;rio no ecr&#227; (y aponta para baixo)
  var NUM      = 13;                         // n&#250;mero de bolas
  var BR       = 14;                         // raio das bolas (px)
  var GRAV     = 1000;                       // gravidade (px/s^2)
  var REST     = 0.82;                       // coeficiente de restitui&#231;&#227;o
  var MU_WALL  = 0.35;                       // fric&#231;&#227;o de contacto bola-parede
  var MU_PAIR  = 0.25;                       // fric&#231;&#227;o de contacto bola-bola
  var AIR_LIN  = 0.12;                       // arrasto line&#225;r do ar (1/s)
  var AIR_QUAD = 0.0006;                     // arrasto quadr&#225;tico do ar (1/px)
  var SPIN_DMP = 0.25;                       // amortecimento do spin (1/s)
  var SUB_H    = 1 / 240;                    // subpasso base da integra&#231;&#227;o (s)
  var WORLD    = 900;                        // tamanho l&#243;gico do mundo (px)
  var CX = WORLD / 2, CY = WORLD / 2;        // centro do pol&#237;gono (referencial do canvas)

  var canvas = document.getElementById('c');
  var ctx    = canvas.getContext('2d');

  var t = 0;          // tempo da simula&#231;&#227;o (s)
  var balls = [];

  /* ============ arranque: bolas pr&#243;ximas do centro, velocidade nula ============ */
  function initState() {
    t = 0;
    balls.length = 0;
    for (var i = 0; i < NUM; i++) {
      var ox = 0, oy = 0;
      if (i > 0) {
        var a0 = (i - 1) * 2 * Math.PI / 12;
        ox = Math.cos(a0) * 60;
        oy = Math.sin(a0) * 60;
      }
      balls.push({
        id: i,
        x: CX + ox,
        y: CY + oy,
        r: BR,
        vx: 0,
        vy: 0,
        w: 0,                                  // spin rad/s (hor&#225;rio positivo)
        theta: (i * 2.39996322972865332) % (2 * Math.PI)
      });
    }
    render();
  }

  /* ======================= geometria ======================= */
  function polyVerts(angle) {
    var v = [];
    var base = -Math.PI / 2;
    for (var k = 0; k < SIDES; k++) {
      var a = base + angle + k * (2 * Math.PI / SIDES);
      v.push([CX + POLY_R * Math.cos(a), CY + POLY_R * Math.sin(a)]);
    }
    return v;
  }

  /* ================= bola-parede (parede em movimento) =================
     Para cada aresta: ponto mais pr&#243;ximo q do centro da bola;
     se |b-q| < r h&#225; penetra&#231;&#227;o. A normal &#233; n = (b-q)/|..|
     (apontando para dentro do pol&#237;gono, na frente).
     A velocidade da parede no ponto de impacto &#233;
     v_parede = OMEGA * perp(q - C),  perp(a) = (-a.y, a.x),
     porque o pol&#237;gono gira como r&#237;gido com OMEGA em torno de C.
     O impulso normal usa a velocidade *relativa* &#224; parede:
         Jn = -(1+e) * ((v - v_parede) &#183; n)
     O atrito tangencial inclui o spin da bola: a velocidade do ponto de
     contacto da bola &#233; v + w &#215; (-r n), ou seja, v - r w t&#770;,
     t&#770; = (-n.y, n.x). Impulso tangencial limitado por &#956; |Jn|
     (Coulomb). A in&#233;rcia da bola &#233; I = 1/2 m r&#178; com m = 1.
  ===================================================================== */
  function solveWall(b, verts) {
    var acted = false;
    for (var e = 0; e < SIDES; e++) {
      var A = verts[e], B = verts[(e + 1) % SIDES];
      var abx = B[0] - A[0], aby = B[1] - A[1];
      var ab2 = abx * abx + aby * aby;
      var tt = ((b.x - A[0]) * abx + (b.y - A[1]) * aby) / ab2;
      if (tt < 0) tt = 0;
      else if (tt > 1) tt = 1;
      var qx = A[0] + abx * tt, qy = A[1] + aby * tt;
      var dx = b.x - qx, dy = b.y - qy;
      var d2 = dx * dx + dy * dy;
      if (d2 >= b.r * b.r) continue;                     // sem contacto nesta aresta
      var dist = Math.sqrt(d2);
      var nx, ny;
      if (dist > 1e-9) {
        nx = dx / dist; ny = dy / dist;
      } else {
        // centro exatamente sobre a reta da aresta: usa a normal interior
        var el = Math.sqrt(ab2);
        nx = -aby / el; ny = abx / el;
        if ((CX - A[0]) * nx + (CY - A[1]) * ny < 0) { nx = -nx; ny = -ny; }
        dist = 0;
      }

      // corre&#231;&#227;o de posi&#231;&#227;o: empurra a bola para dentro
      b.x += nx * (b.r - dist);
      b.y += ny * (b.r - dist);
      acted = true;

      // velocidade da parede no ponto de impacto
      var rx = qx - CX, ry = qy - CY;
      var wvx = -OMEGA * ry, wvy = OMEGA * rx;

      var vn = (b.vx - wvx) * nx + (b.vy - wvy) * ny;
      if (vn < 0) {                                       // em aproxima&#231;&#227;o
        var Jn = -(1 + REST) * vn;                        // m = 1
        b.vx += Jn * nx;
        b.vy += Jn * ny;

        // fric&#231;&#227;o tangencial de Coulomb (inclui o spin da bola)
        var tx = -ny, ty = nx;
        var vt = (b.vx - wvx) * tx + (b.vy - wvy) * ty - b.w * b.r;
        var Jt = -vt / 3;                                 // 1/m + r&#178;/I = 1 + 2
        var cap = MU_WALL * Jn;
        if (Jt > cap) Jt = cap;
        else if (Jt < -cap) Jt = -cap;
        b.vx += Jt * tx;
        b.vy += Jt * ty;
        b.w  += (-rTorque(b, Jt));                        // &#945; = (r &#215; F)/I
      }
    }
    return acted;
  }

  // altera&#231;&#227;o do spin de uma bola por um impulso Jt na dire&#231;&#227;o tangencial
  function rTorque(b, Jt) {
    // torque em torno do centro = -r*Jt (n &#215; t = 1), I = 1/2 r&#178;
    return 2 * Jt / b.r;
