     Mesma equa&#231;&#227;o de impulsos, com o contact point no ponto m&#233;dio
     dos centros (offsets &#177; (d/2) n). A restitui&#231;&#227;o usa a velocidade
     relativa normal; o atrito usa a velocidade tangencial relativa dos
     pontos de contacto, incluindo os spins w de ambas as bolas.
  ===================================================================== */
  function solvePair(p, q) {
    var dx = q.x - p.x, dy = q.y - p.y;
    var minD = p.r + q.r;
    var d2 = dx * dx + dy * dy;
    if (d2 >= minD * minD) return false;
    var dist = Math.sqrt(d2);
    var nx, ny;
    if (dist > 1e-9) { nx = dx / dist; ny = dy / dist; }
    else { nx = 1; ny = 0; dist = 0; }

    // separa&#231;&#227;o posicional (metade para cada bola)
    var pen = minD - dist;
    p.x -= nx * pen * 0.5; p.y -= ny * pen * 0.5;
    q.x += nx * pen * 0.5; q.y += ny * pen * 0.5;

    var vn = (q.vx - p.vx) * nx + (q.vy - p.vy) * ny;
    if (vn >= 0) return true;

    var Jn = -(1 + REST) * vn * 0.5;                      // massas iguais m = 1
    p.vx -= Jn * nx; p.vy -= Jn * ny;
    q.vx += Jn * nx; q.vy += Jn * ny;

    // fric&#231;&#227;o tangencial
    var tx = -ny, ty = nx;
    var vt = (q.vx - p.vx) * tx + (q.vy - p.vy) * ty - 0.5 * dist * (p.w + q.w);
    var Jt = -vt / (2 + dist * dist / (BR * BR));         // 2 + (d/2)&#178;/I * 2
    var cap = MU_PAIR * Jn;
    if (Jt > cap) Jt = cap;
    else if (Jt < -cap) Jt = -cap;
    p.vx -= Jt * tx; p.vy -= Jt * ty;
    q.vx += Jt * tx; q.vy += Jt * ty;
    var dw = -Jt * dist / (BR * BR);                      // (d/2)/I aplicado a cada uma
    p.w += dw;
    q.w += dw;
    return true;
  }

  /* ============================ um subpasso ============================ */
  function substep(h) {
    t += h;
    var verts = polyVerts(t * OMEGA);                     // paredes nesta instante
    var b, k, sp, kd, it, i, j, acting;

    // for&#231;as: gravidade + arrasto do ar + amortecimento do spin
    for (k = 0; k < NUM; k++) {
      b = balls[k];
      sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
      kd = AIR_LIN + AIR_QUAD * sp;
      b.vx -= kd * b.vx * h;
      b.vy += (GRAV - kd * b.vy) * h;
      b.w  *= Math.max(0, 1 - SPIN_DMP * h);
      b.x  += b.vx * h;
      b.y  += b.vy * h;
      b.theta += b.w * h;                                 // o n&#250;mero gira com a bola
    }

    // resolu&#231;&#227;o iterativa: paredes e pares, at&#233; estabilizar
    for (it = 0; it < 6; it++) {
      acting = false;
      for (k = 0; k < NUM; k++) acting = solveWall(balls[k], verts) || acting;
      for (i = 0; i < NUM - 1; i++)
        for (j = i + 1; j < NUM; j++)
          acting = solvePair(balls[i], balls[j]) || acting;
      if (!acting) break;
    }
  }

  /* ============ avan&#231;ar determin&#233;ticamente dt segundos ============ */
  function advance(dtIn) {
    var dt = (typeof dtIn === 'number' && isFinite(dtIn) && dtIn > 0) ? dtIn : 0;
    if (dt > 0.5) dt = 0.5;
    if (dt <= 0) { render(); return; }
    var n = Math.ceil(dt / SUB_H - 1e-7);
    if (n < 1) n = 1;
    var h = dt / n;
    for (var i = 0; i < n; i++) substep(h);
    render();
  }

  /* ============================ render ============================ */
  function render() {
    var W = canvas.width, H = canvas.height;
    if (!W || !H) return;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#0b0f14';
    ctx.fillRect(0, 0, W, H);

    var scale = Math.min(W, H) * 0.94 / WORLD;
    ctx.setTransform(scale, 0, 0, scale,
                     (W - WORLD * scale) / 2, (H - WORLD * scale) / 2);

    var verts = polyVerts(t * OMEGA);
    ctx.beginPath();
    ctx.moveTo(verts[0][0], verts[0][1]);
    for (var k = 1; k < SIDES; k++) ctx.lineTo(verts[k][0], verts[k][1]);
    ctx.closePath();
    ctx.fillStyle = 'rgba(74, 168, 255, 0.055)';
    ctx.fill();
    ctx.lineJoin = 'round';
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#4aa8ff';
    ctx.stroke();

    for (var i = 0; i < NUM; i++) {
      var b = balls[i];
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, 2 * Math.PI);
      ctx.fillStyle = 'hsl(' + (i * 360 / NUM) + ', 62%, 55%)';
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = 'rgba(0,0,0,0.45)';
      ctx.stroke();

      // n&#250;mero desenhado sobre a bola, rotacionado com o spin dela
      ctx.save();
      ctx.translate(b.x, b.y);
      ctx.rotate(b.theta);
      ctx.fillStyle = '#0a121c';
      ctx.font = '700 13px system-ui, -apple-system, "Segoe UI", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(b.id), 0, 0.5);
      ctx.restore();
    }
  }

  function resize() {
    canvas.width  = window.innerWidth  || WORLD;
    canvas.height = window.innerHeight || WORLD;
    render();
  }
  window.addEventListener('resize', resize);
  resize();

  /* ==================== loop de anima&#231;&#227;o ====================
     Corre via requestAnimationFrame enquanto `auto` estiver ativo.
     Quando o h&#225;mio de verifica&#231;&#227;o chama step(), a anima&#231;&#227;o
     autom&#225;tica fica pausada e a simula&#231;&#227;o passa a ser movida
     exclusivamente pelas chamadas step(dt). play() retoma a anima&#231;&#227;o.
  ===================================================================== */
  var auto = true;
  var lastTime = null;
  function frame(now) {
    requestAnimationFrame(frame);
    if (!auto) { lastTime = null; return; }
    if (lastTime === null) { lastTime = now; return; }
    var dt = (now - lastTime) / 1000;
    lastTime = now;
    if (dt <= 0) return;
    if (dt > 0.05) dt = 0.05;
    advance(dt);
  }
  requestAnimationFrame(frame);

  /* ==================== contrato de verifica&#231;&#227;o ==================== */
  window.__bench = {
    getState: function () {
      return {
        t: t,
        poly: {
          n: SIDES,
          radius: POLY_R,
          cx: CX,
          cy: CY,
          angle: t * OMEGA,
          periodSec: PERIOD
        },
        balls: balls.map(function (b) {
          return { id: b.id, x: b.x, y: b.y, r: b.r, vx: b.vx, vy: b.vy };
        })
      };
    },
    step: function (dt) {
      auto = false;
      lastTime = null;
      advance(dt);
    },
    play: function () {
      auto = true;
      lastTime = null;
    },
    pause: function () {
      auto = false;
    },
    reset: function () {
      initState();
    }
  };

  initState();
})();
</script>
</body>
</html>
'''

